// @ts-check
/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

import { Command } from '../../../utils/Command.js'
import { CommandType } from '../../../utils/CommandType.js'
import { RuntimeName } from '../../../utils/RuntimeName.js'
import { Color, Duration, Point, Uuid, colorChannel } from '../../../utils/DrawingTypes.js'
import { getCurrentCommandPayload } from './TypeParsingUtils.js'

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseDate(invocationContext) {
    const value = getCurrentCommandPayload(invocationContext)[1]
    return new Date(value)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {URL}
 */
export function parseURL(invocationContext) {
    return new URL(String(getCurrentCommandPayload(invocationContext)[1]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Point}
 */
export function parsePoint(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    return new Point(Number(payload[1]), Number(payload[2]))
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Color}
 */
export function parseColor(invocationContext) {
    const payload = getCurrentCommandPayload(invocationContext)
    const a = Number(payload[1]) & 0xff
    const r = Number(payload[2]) & 0xff
    const g = Number(payload[3]) & 0xff
    const b = Number(payload[4]) & 0xff
    return new Color(r, g, b, a)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {string}
 */
export function parseUUID(invocationContext) {
    return String(getCurrentCommandPayload(invocationContext)[1])
}

/** Inbound: Node.js result type string → JavaScript object */
export const NodejsTypeParsingFunctions = new Map(
    /** @type {[string, (invocationContext: InvocationContext) => unknown][]} */ ([
        ['Date', parseDate],
        ['URL', parseURL],
        ['Point', parsePoint],
        ['Color', parseColor],
        ['UUID', parseUUID],
    ])
)

/** Outbound: JavaScript object → Command graph targeting the Node.js runtime */
export const NodejsParsingArgument = new Map(
    /** @type {[Function, (value: any) => Command][]} */ ([
        [
            Date,
            (/** @type {Date} */ value) =>
                new Command(RuntimeName.Nodejs, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Nodejs, CommandType.GetType, ['Date']),
                    value.toISOString(),
                ]),
        ],
        [
            URL,
            (/** @type {URL} */ value) =>
                new Command(RuntimeName.Nodejs, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Nodejs, CommandType.GetType, ['URL']),
                    value.href,
                ]),
        ],
        [
            Duration,
            (/** @type {Duration} */ value) =>
                new Command(RuntimeName.Nodejs, CommandType.Value, [value.milliseconds]),
        ],
        [
            Uuid,
            (/** @type {Uuid} */ value) => new Command(RuntimeName.Nodejs, CommandType.Value, [value.value]),
        ],
        [
            Point,
            (/** @type {Point} */ value) =>
                new Command(RuntimeName.Nodejs, CommandType.ComplexValueType, ['Point', value.x, value.y]),
        ],
        [
            Color,
            (/** @type {Color} */ value) =>
                new Command(RuntimeName.Nodejs, CommandType.ComplexValueType, [
                    'Color',
                    colorChannel(value.a),
                    colorChannel(value.r),
                    colorChannel(value.g),
                    colorChannel(value.b),
                ]),
        ],
    ])
)
